messages.content:
Tool response:
Tool: create_gold_fitness_plan
Description: Create Subscription Plan
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "tiers": {
          "items": {
            "properties": {
              "name": {
                "type": "string",
                "title": "Name"
              },
              "monthly_price": {
                "type": "number",
                "title": "Monthly Price"
              },
              "trial_days": {
                "type": "integer",
                "title": "Trial Days"
              },
              "annual_discount_percent": {
                "anyOf": [
                  {
                    "type": "number"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Annual Discount Percent",
                "default": 0.0
              }
            },
            "type": "object",
            "required": [
              "name",
              "monthly_price",
              "trial_days"
            ],
            "title": "TierInput"
          },
          "type": "array",
          "title": "Tiers"
        }
      },
      "required": [
        "name",
        "tiers"
      ]
    }
